import java.util.Scanner;

public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    long X = sc.nextLong();
    long result;
    if (X > 0) {
        result = ((X - 1) / 10) + 1;
    } else {
        if (X % 10 == 0) {
            result = X / 10;
        } else {
            result = (X / 10) - 1;
        }
    }

    System.out.println(result);
}
